import React, { useMemo, useEffect, useState, useRef, memo } from "react";
import { useQuery } from "@tanstack/react-query";
import { profileService } from "@/features/profile/services/profileService";
import { mealService } from "../services/mealService";
import { useCalculatedProfile } from "@/shared/hooks/useCalculatedProfile";
import { useUserStore } from "@/features/profile/store/userStore";
import { reportService } from "@/features/reports/services/reportService";
import { DailyHistoryChart } from "../components/DailyHistoryChart";
import { ChevronLeft, Utensils, AlertTriangle, Loader2 } from "lucide-react";
import { motion } from "motion/react";
import { cn } from "@/shared/utils/utils";
import { EmptyState } from '@/shared/components/EmptyState';
import { useNetworkConnectivity } from '@/shared/hooks/useNetworkConnectivity';
import { NutritionDetailSkeleton } from '@/shared/components/Skeletons';

const AnimatedNumber = memo(function AnimatedNumber({ value, duration = 800 }: { value: number; duration?: number }) {
  const [displayValue, setDisplayValue] = useState(0);
  const elementRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    let observer: IntersectionObserver;
    let animationFrameId: number;
    let start: number | null = null;
    let lastUpdate = 0;
    const update = (time: number) => {
      if (!start) start = time;
      const elapsed = time - start;
      if (time - lastUpdate > 32 || elapsed >= duration) {
        lastUpdate = time;
        const progress = Math.min(elapsed / duration, 1);
        const ease = 1 - Math.pow(1 - progress, 4);
        const nextValue = Math.round(ease * value);
        setDisplayValue(prev => (prev !== nextValue ? nextValue : prev));
      }
      if (elapsed < duration) {
        animationFrameId = requestAnimationFrame(update);
      }
    };
    const startAnimation = () => {
      start = null;
      lastUpdate = 0;
      animationFrameId = requestAnimationFrame(update);
    };
    if (elementRef.current) {
      observer = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting) {
          startAnimation();
          observer.disconnect();
        }
      }, { threshold: 0.1 });
      observer.observe(elementRef.current);
    }
    return () => {
      if (animationFrameId) cancelAnimationFrame(animationFrameId);
      if (observer) observer.disconnect();
    };
  }, [value, duration]);
  return <span ref={elementRef}>{displayValue}</span>;
});

function getLocalDateString(d: Date = new Date()) {
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

export function ProteinDetailPage() {
  const navigate = useNavigate();
  const isOnline = useNetworkConnectivity();
  const { profileData: onboardingData } = useCalculatedProfile();
  const { data: metrics = [] } = useQuery({ queryKey: ["dailyMetrics"], queryFn: () => reportService.getDailyMetrics() });
  const { data: profile } = useQuery({ queryKey: ["profile"], queryFn: () => profileService.getProfile() });
  const { data: goal } = useQuery({ queryKey: ["goal"], queryFn: () => profileService.getGoal() });
  const { data: meals = [], isLoading } = useQuery({ queryKey: ["meals", "month"], queryFn: () => mealService.getMeals({ days: 35, limit: 2000 }) });

  const target_protein = onboardingData?.targetMacros?.protein ?? 150;

  const todayStr = getLocalDateString();
  const todayMeals = meals.filter(m => {
    const d = new Date(m.meal_time);
    const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    return dateStr === todayStr;
  });
  const proteinConsumed = todayMeals.reduce((acc, m) => acc + m.protein, 0);
  
  const chartLogs = useMemo(() => {
    const logs = [...metrics];
    
    // Group all meals by date
    const mealsByDate = meals.reduce((acc: any, m: any) => {
      const d = new Date(m.meal_time);
      const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
      if (!acc[dateStr]) acc[dateStr] = 0;
      acc[dateStr] += m.protein;
      return acc;
    }, {});

    // Overwrite actuals with dynamically aggregated meals
    logs.forEach(l => {
      if (mealsByDate[l.date] !== undefined) {
        l.actual_protein = mealsByDate[l.date];
      } else {
        l.actual_protein = 0;
      }
    });

    const logDates = new Set(logs.map(l => l.date));
    Object.keys(mealsByDate).forEach(dateStr => {
      if (!logDates.has(dateStr)) {
        logs.push({
          date: dateStr,
          actual_protein: mealsByDate[dateStr],
          target_protein: target_protein,
          actual_calories: 0,
          target_calories: 0,
          user_id: "", water: 0, score: 0
        });
      }
    });

    const todayIdx = logs.findIndex(l => l.date === todayStr);
    if (todayIdx >= 0) {
      logs[todayIdx] = { ...logs[todayIdx], actual_protein: proteinConsumed, target_protein };
    } else {
      logs.push({
        date: todayStr,
        actual_calories: 0, user_id: "", water: 0, score: 0,
        actual_protein: proteinConsumed,
        target_calories: 0,
        target_protein,
      });
    }
    return logs;
  }, [metrics, meals, todayStr, proteinConsumed, target_protein]);

  const chartData = useMemo(() => {
    return chartLogs.map(l => ({
      date: l.date,
      actual: l.actual_protein,
      target: l.target_protein
    }));
  }, [chartLogs]);

  const slots = [
    { id: 'breakfast', label: 'Breakfast', items: todayMeals.filter(m => m.meal_slot === 'breakfast') },
    { id: 'lunch', label: 'Lunch', items: todayMeals.filter(m => m.meal_slot === 'lunch') },
    { id: 'dinner', label: 'Dinner', items: todayMeals.filter(m => m.meal_slot === 'dinner') },
    { id: 'other', label: 'Snacks / Other', items: todayMeals.filter(m => !['breakfast', 'lunch', 'dinner'].includes(m.meal_slot || '')) },
  ];

  const proPct = target_protein ? Math.min(proteinConsumed / target_protein, 1.1) : 0;

  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);

  if (isLoading) {
    if (!isOnline) {
      return (
        <div className="min-h-screen bg-[#0A0A0A] pb-[100px] flex flex-col items-center justify-center px-6 text-center">
          <AlertTriangle className="w-12 h-12 text-[rgba(255,255,255,0.2)] mb-4" />
          <h2 className="text-[18px] font-semibold text-white mb-2">You're offline</h2>
          <p className="text-[14px] text-[rgba(255,255,255,0.6)]">
            Connect to the internet to load your protein details for the first time.
          </p>
          <button onClick={() => navigate('/dashboard')} className="mt-8 text-[#378ADD] font-medium text-[15px]">
            Return to Dashboard
          </button>
        </div>
      );
    }
    return <NutritionDetailSkeleton />;
  }

  return (
    <div className="page-enter pt-[calc(env(safe-area-inset-top)+20px)] pb-[calc(100px+env(safe-area-inset-bottom))] min-h-[100dvh] bg-[#0A0A0A] px-5">
      {/* Header */}
      <div className="flex items-center justify-between mb-10">
        <button onClick={() => navigate("/dashboard")} aria-label="Back to dashboard" className="w-[44px] h-[44px] rounded-full bg-[rgba(255,255,255,0.03)] flex items-center justify-center transition-colors hover:bg-[rgba(255,255,255,0.1)]">
          <ChevronLeft size={20} className="text-white" />
        </button>
        <h1 className="text-[17px] font-semibold text-white tracking-tight">Protein</h1>
        <div className="w-8" />
      </div>

      {/* Hero Number Section */}
      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="flex flex-col items-center justify-center text-center mb-12 mt-6">
        <div className="flex items-baseline gap-1.5 mb-2">
          <span className="text-[64px] font-bold text-white tracking-tighter leading-none"><AnimatedNumber value={proteinConsumed} /></span>
        </div>
        <div className="text-[16px] font-medium text-[rgba(235,235,245,0.45)] mb-8 tracking-wide">of {target_protein} g</div>
        
        {/* Progress bar */}
        <div className="w-full max-w-[280px] progress-track h-2 rounded-full overflow-hidden bg-[rgba(255,255,255,0.1)] shadow-inner">
          <div 
            className="h-full rounded-full transition-all duration-1000 ease-out bg-[#378ADD]" 
            style={{ width: mounted ? `${Math.min(100, proPct * 100)}%` : '0%' }} 
          />
        </div>
      </motion.div>

      {/* 7-Day History Chart */}
      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }} className="rounded-[24px] bg-[rgba(255,255,255,0.03)] border border-[rgba(255,255,255,0.05)] p-6 mb-10 shadow-sm backdrop-blur-xl">
        <div className="text-[12px] font-semibold text-[rgba(235,235,245,0.5)] uppercase tracking-widest mb-6">Daily protein history</div>
        <DailyHistoryChart 
          logs={chartData} 
          todayStr={todayStr} 
          startDateStr={goal?.created_at ? getLocalDateString(new Date(goal.created_at)) : undefined}
          unit="g" 
          type="protein" 
        />
      </motion.div>

      {/* Meal Breakdown Section */}
      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }} className="stagger-children">
        <div className="text-[12px] font-semibold text-[rgba(235,235,245,0.5)] uppercase tracking-widest mb-4 px-1">Today's Meals</div>
        
        {todayMeals.length === 0 ? (
          <EmptyState
            icon={Utensils}
            title="No meals logged yet"
            description="Your daily meal log is empty. Tap the button below to add your first meal."
            ctaText="Log Meal"
            onCtaClick={() => navigate('/log-meal')}
            className="py-10"
          />
        ) : (
          <div>
            {slots.filter(s => s.items.length > 0).map(slot => {
              const slotPro = slot.items.reduce((a, b) => a + b.protein, 0);
              return (
                <div key={slot.id} className="rounded-[24px] bg-[rgba(255,255,255,0.03)] border border-[rgba(255,255,255,0.05)] mb-4 overflow-hidden shadow-sm backdrop-blur-xl">
                  <div className="flex items-center justify-between p-5 bg-[rgba(255,255,255,0.02)] border-b border-[rgba(255,255,255,0.06)]">
                    <span className="text-[16px] font-bold text-white tracking-tight">{slot.label}</span>
                    <span className="text-[15px] font-bold tracking-tight text-white">{slotPro} g</span>
                  </div>
                  <div className="px-5 py-2">
                    {slot.items.map((item, i) => (
                      <div key={item.id || i} className={cn("flex items-center justify-between py-3.5", i < slot.items.length - 1 && "border-b border-[rgba(255,255,255,0.06)]")}>
                        <span className="text-[15px] font-medium text-[rgba(255,255,255,0.85)] leading-relaxed capitalize pr-4">{item.meal_text}</span>
                        <span className="text-[14px] font-bold tracking-tight text-[#378ADD] bg-[rgba(55,138,221,0.1)] px-2.5 py-1 rounded-full shrink-0">{item.protein} g</span>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </motion.div>
    </div>
  );
}
